package net.civeira.phylax.features.access.userprofile.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class MiddleNameVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property middle name of user profile ")
  void test_middle_name_v_o_builder() {
    Assertions.assertFalse(MiddleNameVO.nullValue().getMiddleName().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(MiddleNameVO.tryFrom(null).getMiddleName().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", MiddleNameVO.from("one").getMiddleName().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> MiddleNameVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", MiddleNameVO.from("one").toString());
  }
}
